mapper.select:
SELECT * FROM
(SELECT
b.*,
a.store_favorite_num,
a.store_sales_num,
a.store_evaluation_rate,
(ST_Distance(store_location, POINT(#{params.lng}, #{params.lat})) * 111195) AS distance
FROM
shop_store_base b
INNER JOIN
shop_store_analytics a
ON b.store_id=a.store_id


        and b.store_id=#{params.storeId}


        and b.store_category_id=#{params.storeCategoryId}


        and b.store_is_open=#{params.storeIsOpen}


        and b.store_type=#{params.storeType}


        and b.store_name like concat('%', #{params.storeName}, '%')


        ORDER BY `${params.sidx}` ${params.sort}


) tempTable



        distance <= #{params.distance}
